package cl.felipe.agrofrost.domain.entity;
import cl.felipe.agrofrost.domain.model.FrostRiskLevel; import cl.felipe.agrofrost.domain.valueobject.*; import org.junit.jupiter.params.ParameterizedTest; import org.junit.jupiter.params.provider.CsvSource; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class FieldTest { private Field field() { return new Field(new FieldId("f-1"), new FieldName("North"), new Crop("Grapes"), new CriticalTemperature(0)); } @Test void hasValueObjectIdentityAndAttributes() { Field field=field(); assertEquals(new FieldId("f-1"), field.id()); assertEquals(new FieldName("North"), field.name()); assertEquals(new Crop("Grapes"), field.crop()); assertEquals(new CriticalTemperature(0), field.criticalTemperature()); } @ParameterizedTest @CsvSource({"-1.0, CRITICAL", "0.0, CRITICAL", "1.5, WARNING", "2.0, WARNING", "2.1, SAFE"}) void assessesFrostAtExactBoundaries(double measured, FrostRiskLevel expected) { FrostAssessment assessment=field().assessFrost(new MeasuredTemperature(measured)); assertEquals(expected, assessment.riskLevel()); } @Test void rejectsNullConstructionPartsAndMeasurement() { assertAll(() -> assertThrows(NullPointerException.class, () -> new Field(null, new FieldName("n"), new Crop("c"), new CriticalTemperature(0))), () -> assertThrows(NullPointerException.class, () -> new Field(new FieldId("i"), null, new Crop("c"), new CriticalTemperature(0))), () -> assertThrows(NullPointerException.class, () -> new Field(new FieldId("i"), new FieldName("n"), null, new CriticalTemperature(0))), () -> assertThrows(NullPointerException.class, () -> new Field(new FieldId("i"), new FieldName("n"), new Crop("c"), null)), () -> assertThrows(NullPointerException.class, () -> field().assessFrost(null))); } }
